    @Column(name = "retired_made_on")
    private LocalDate retiredMadeOn;

    /** The sheet they were transferred from (null: they were not transferred here). */
    @Column(name = "origin_sheet")
    private String originSheet;

    /** The sheet's today when a transfer brought them here (null: they did not arrive by transfer). */
    @Column(name = "arrived_on")
    private LocalDate arrivedOn;

    protected Person() {
    }

    public Person(String sheetId, String name, String grade) {
        this.sheetId = sheetId;
        this.name = name;
        this.grade = grade;
    }

    public Long getId() {
        retirements.add(new PersonRetirement(retiredFrom, on, retiredMadeOn, on));
        this.retiredFrom = null;
        this.retiredMadeOn = null;
    }

    /** A copy of them as they stood at the end of a date: only the holds and retirement made while the sheet's
     *  today was on or before it. Only worked out, never saved. */
    public Person asOf(LocalDate date) {
        Person then = new Person(sheetId, name, grade);
        then.id = id;
        then.position = position;
        then.terms = terms;
        then.contact = contact;
        then.tags = tags;
        then.addedOn = addedOn;
        if (retiredMadeOn == null || !retiredMadeOn.isAfter(date)) {
            then.retiredFrom = retiredFrom;
            then.retiredMadeOn = retiredMadeOn;
        }
        for (PersonRetirement r : retirements) {
            if (r.madeBy(date)) {
                then.retirements.add(r);
            } else if (r.retiredBy(date)) {
                then.retiredFrom = r.getFromDate();
                then.retiredMadeOn = r.getRetireMadeOn();
            }
        }
        holds.stream().filter(h -> h.madeBy(date)).forEach(then.holds::add);
        snapshots.stream().filter(s -> !s.getTakenOn().isAfter(date)).forEach(then.snapshots::add);
        return then;
    }

    public LocalDate getRetiredFrom() {
        return retiredFrom;
    }

    public List<PersonRetirement> getRetirements() {
        return retirements;
    }

    public List<PersonSnapshot> getSnapshots() {
        return snapshots;
    }

    /** Records their due-total on the day being left as the sheet's today moves on. */
    public void addSnapshot(PersonSnapshot snapshot) {
        snapshots.add(snapshot);
    }

    public List<PersonHold> getHolds() {
        return holds;
    }

    public void addHold(PersonHold hold) {
        holds.add(hold);
    }

    /** Whether they have any hold. */
    public boolean isHeld() {
        return !holds.isEmpty();
    }

    /** Whether a hold of theirs covers the date. */
    public boolean heldOn(LocalDate date) {
        return holds.stream().anyMatch(h -> h.covers(date));
    }

    /** Whether their retirement date is reached on the day: it is on or before it. */
    public boolean retiredBy(LocalDate today) {
        return retiredFrom != null && today != null && !today.isBefore(retiredFrom);
    }

    /** Whether their OPEN and PENDING claims on the date leave the live totals on the day: a hold of theirs covers
     *  the date, or their retirement date is reached. */
    public boolean leftOn(LocalDate date, LocalDate today) {
        return heldOn(date) || retiredBy(today);
    }

    /** Whether a claim on this date is refused: it is after their retirement date, or after the from and before the
     *  to of a past retirement. */
    public boolean retiredOn(LocalDate date) {
        return (retiredFrom != null && date.isAfter(retiredFrom))
                || retirements.stream().anyMatch(r -> r.refuses(date));
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import net.officefloor.hq.app.statement.Statement;

/** A person as the screen shows them: their grade in force on the sheet's today, and every grade they were given
 *  with its from-date (null for the first, which applies from the beginning of time), with their statement count
 *  and their last statement's due-total and date (null with none), and the date they are retired from (null: not
 *  retired), and whether they have any hold, and their holds (earliest first), and the ids of their patrons in the order they were named, and their own terms in days in force on the sheet's today (null: none), and their contact (null: none), and their aliases, sorted ignoring case, and whether
 *  they clash: their name or an alias is in use on another sheet of the sheet's tree, and the sheet they were
 *  transferred from (null: none), and their past retirements (earliest first), and their tags, sorted, and their snapshots, oldest first, and their statements, by
 *  the date each was taken as of (in the order they stand on the same date). */
public record PersonResponse(long id, String name, String grade, List<DatedGrade> grades, long version,
        int statementCount, String statedTotal, String statementDate, String retiredFrom, boolean held,
        List<Hold> holds, List<Long> patronIds, Integer terms,
        String contact, List<String> aliases, boolean clashing, String origin,
        List<Retirement> retirements, List<String> tags, List<Snapshot> snapshots,
        List<StatementLine> statements) {

    /** A statement still standing: the date it was taken as of and the due-total it recorded. */
    public record StatementLine(String date, String dueTotal) {
    }

    /** A past retirement, from a date to the day they were unretired. */
    public record Retirement(String from, String to) {
    }

    /** A snapshot: the day being left when the sheet's today moved on, and their due-total on it. */
    public record Snapshot(String date, String dueTotal) {
    }

    /** A hold from a date on, to a date (inclusive; null: open-ended). */
    public record Hold(String from, String to) {
    }

    /** A grade from a date on (null: from the beginning of time). */
    public record DatedGrade(String grade, String from) {
    }

    /** @param statements the person's statements, oldest first.
     *  @param patrons the person's patrons, in the order they were named.
     *  @param grades the person's grades over time.
     *  @param aliases the person's aliases.
     *  @param today the sheet's today.
     *  @param usedAround the names and aliases, lower-cased, in use on the other sheets of the sheet's tree. */
    public static PersonResponse from(Person person, List<Statement> statements, List<Patron> patrons,
            List<PersonAlias> aliases, PersonGrades grades, LocalDate today,
            java.util.Set<String> usedAround) {
        Statement last = statements.isEmpty() ? null : statements.get(statements.size() - 1);
        List<DatedGrade> dated = new ArrayList<>();
        dated.add(new DatedGrade(grades.first(), null));
        grades.dated().forEach(g -> dated.add(new DatedGrade(g.getGrade(), g.getFromDate().toString())));
        return new PersonResponse(person.getId(), person.getName(), grades.on(today), dated, person.getVersion(),
                statements.size(), last == null ? null : last.getDueTotal(),
                last == null ? null : last.getTakenOn().toString(),
                person.getRetiredFrom() == null ? null : person.getRetiredFrom().toString(), person.isHeld(),
                person.getHolds().stream().map(h -> new Hold(h.getFromDate().toString(),
                        h.getToDate() == null ? null : h.getToDate().toString())).toList(),
                patrons.stream().map(Patron::getPatronId).toList(), person.termsOn(today), person.getContact(),
                aliases.stream().map(PersonAlias::getAlias)
                        .sorted(String.CASE_INSENSITIVE_ORDER.thenComparing(java.util.Comparator.naturalOrder()))
                        .toList(),
                usedAround.contains(TreeNames.key(person.getName()))
                        || aliases.stream().anyMatch(a -> usedAround.contains(TreeNames.key(a.getAlias()))),
                person.getOriginSheet(),
                person.getRetirements().stream().map(r -> new Retirement(r.getFromDate().toString(),
                        r.getToDate().toString())).toList(),
                net.officefloor.hq.app.claim.Tags.list(person.getTags()),
                person.getSnapshots().stream().map(s -> new Snapshot(s.getTakenOn().toString(), s.getDueTotal()))
                        .toList(),
                statements.stream().sorted(java.util.Comparator.comparing(Statement::getTakenOn))
                        .map(st -> new StatementLine(st.getTakenOn().toString(), st.getDueTotal())).toList());
    }
}
